PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE regions (
                region_id INTEGER PRIMARY KEY AUTOINCREMENT,
                region_name TEXT NOT NULL,
                country TEXT NOT NULL,
                population INTEGER,
                area_km2 REAL,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE categories (
                category_id INTEGER PRIMARY KEY AUTOINCREMENT,
                category_name TEXT NOT NULL,
                description TEXT,
                parent_category_id INTEGER REFERENCES categories(category_id),
                is_active INTEGER DEFAULT 1,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE suppliers (
                supplier_id INTEGER PRIMARY KEY AUTOINCREMENT,
                company_name TEXT NOT NULL,
                contact_person TEXT,
                email TEXT,
                phone TEXT,
                address TEXT,
                region_id INTEGER REFERENCES regions(region_id),
                established_year INTEGER,
                rating REAL CHECK (rating >= 0 AND rating <= 5),
                is_active INTEGER DEFAULT 1,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE customers (
                customer_id INTEGER PRIMARY KEY AUTOINCREMENT,
                first_name TEXT NOT NULL,
                last_name TEXT NOT NULL,
                email TEXT UNIQUE,
                phone TEXT,
                birth_date TEXT,
                gender TEXT CHECK (gender IN ('Male', 'Female', 'Other')),
                address TEXT,
                region_id INTEGER REFERENCES regions(region_id),
                customer_type TEXT CHECK (customer_type IN ('Regular', 'Premium', 'VIP')),
                registration_date TEXT DEFAULT CURRENT_DATE,
                last_login TEXT,
                is_active INTEGER DEFAULT 1,
                total_spent REAL DEFAULT 0,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE departments (
                department_id INTEGER PRIMARY KEY AUTOINCREMENT,
                department_name TEXT NOT NULL,
                description TEXT,
                manager_id INTEGER,
                budget REAL,
                established_date TEXT,
                location TEXT,
                is_active INTEGER DEFAULT 1,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE employees (
                employee_id INTEGER PRIMARY KEY AUTOINCREMENT,
                employee_code TEXT UNIQUE,
                first_name TEXT NOT NULL,
                last_name TEXT NOT NULL,
                email TEXT UNIQUE,
                phone TEXT,
                birth_date TEXT,
                hire_date TEXT NOT NULL,
                department_id INTEGER REFERENCES departments(department_id),
                position_title TEXT,
                salary REAL NOT NULL,
                manager_id INTEGER REFERENCES employees(employee_id),
                region_id INTEGER REFERENCES regions(region_id),
                experience_years INTEGER DEFAULT 0,
                education_level TEXT,
                is_active INTEGER DEFAULT 1,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE products (
                product_id INTEGER PRIMARY KEY AUTOINCREMENT,
                product_code TEXT UNIQUE NOT NULL,
                product_name TEXT NOT NULL,
                description TEXT,
                category_id INTEGER REFERENCES categories(category_id),
                supplier_id INTEGER REFERENCES suppliers(supplier_id),
                unit_price REAL NOT NULL,
                cost_price REAL,
                stock_quantity INTEGER DEFAULT 0,
                reorder_level INTEGER DEFAULT 10,
                weight REAL,
                dimensions TEXT,
                color TEXT,
                brand TEXT,
                model TEXT,
                warranty_months INTEGER,
                rating REAL CHECK (rating >= 0 AND rating <= 5),
                reviews_count INTEGER DEFAULT 0,
                is_active INTEGER DEFAULT 1,
                launch_date TEXT,
                discontinue_date TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE orders (
                order_id INTEGER PRIMARY KEY AUTOINCREMENT,
                order_number TEXT UNIQUE NOT NULL,
                customer_id INTEGER REFERENCES customers(customer_id),
                employee_id INTEGER REFERENCES employees(employee_id),
                order_date TEXT NOT NULL,
                required_date TEXT,
                shipped_date TEXT,
                delivery_date TEXT,
                shipping_address TEXT,
                billing_address TEXT,
                region_id INTEGER REFERENCES regions(region_id),
                payment_method TEXT,
                order_status TEXT CHECK (order_status IN ('Pending', 'Processing', 'Shipped', 'Delivered', 'Cancelled')),
                subtotal REAL NOT NULL,
                tax_amount REAL DEFAULT 0,
                shipping_cost REAL DEFAULT 0,
                discount_amount REAL DEFAULT 0,
                total_amount REAL NOT NULL,
                notes TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE order_details (
                order_detail_id INTEGER PRIMARY KEY AUTOINCREMENT,
                order_id INTEGER REFERENCES orders(order_id),
                product_id INTEGER REFERENCES products(product_id),
                quantity INTEGER NOT NULL CHECK (quantity > 0),
                unit_price REAL NOT NULL,
                discount_percent REAL DEFAULT 0,
                line_total REAL NOT NULL,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE reviews (
                review_id INTEGER PRIMARY KEY AUTOINCREMENT,
                product_id INTEGER REFERENCES products(product_id),
                customer_id INTEGER REFERENCES customers(customer_id),
                order_id INTEGER REFERENCES orders(order_id),
                rating INTEGER CHECK (rating >= 1 AND rating <= 5),
                review_title TEXT,
                review_text TEXT,
                review_date TEXT DEFAULT CURRENT_DATE,
                is_verified INTEGER DEFAULT 0,
                helpful_votes INTEGER DEFAULT 0,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE VIEW customer_summary AS
            SELECT
                c.customer_id,
                c.first_name || ' ' || c.last_name as full_name,
                c.email,
                c.customer_type,
                r.region_name,
                c.registration_date,
                COUNT(DISTINCT o.order_id) as total_orders,
                COALESCE(SUM(o.total_amount), 0) as total_spent,
                COALESCE(AVG(o.total_amount), 0) as avg_order_value,
                MAX(o.order_date) as last_order_date
            FROM customers c
            LEFT JOIN regions r ON c.region_id = r.region_id
            LEFT JOIN orders o ON c.customer_id = o.customer_id
            GROUP BY c.customer_id, c.first_name, c.last_name, c.email,
                     c.customer_type, r.region_name, c.registration_date;
CREATE VIEW product_summary AS
            SELECT
                p.product_id,
                p.product_name,
                p.product_code,
                c.category_name,
                s.company_name as supplier_name,
                p.unit_price,
                p.stock_quantity,
                p.rating,
                p.reviews_count,
                COALESCE(order_stats.total_sold, 0) as total_sold,
                COALESCE(order_stats.total_revenue, 0) as total_revenue
            FROM products p
            LEFT JOIN categories c ON p.category_id = c.category_id
            LEFT JOIN suppliers s ON p.supplier_id = s.supplier_id
            LEFT JOIN (
                SELECT
                    product_id,
                    SUM(quantity) as total_sold,
                    SUM(line_total) as total_revenue
                FROM order_details
                GROUP BY product_id
            ) order_stats ON p.product_id = order_stats.product_id;
CREATE VIEW employee_performance AS
            SELECT
                e.employee_id,
                e.first_name || ' ' || e.last_name as full_name,
                e.employee_code,
                d.department_name,
                e.position_title,
                e.salary,
                r.region_name,
                COUNT(DISTINCT o.order_id) as orders_processed,
                COALESCE(SUM(o.total_amount), 0) as total_sales,
                COALESCE(AVG(o.total_amount), 0) as avg_order_value,
                CASE
                    WHEN e.salary > 0 THEN COALESCE(SUM(o.total_amount), 0) / e.salary
                    ELSE 0
                END as sales_to_salary_ratio
            FROM employees e
            LEFT JOIN departments d ON e.department_id = d.department_id
            LEFT JOIN regions r ON e.region_id = r.region_id
            LEFT JOIN orders o ON e.employee_id = o.employee_id
            GROUP BY e.employee_id, e.first_name, e.last_name, e.employee_code,
                     d.department_name, e.position_title, e.salary, r.region_name;
CREATE VIEW sales_by_region AS
            SELECT
                r.region_id,
                r.region_name,
                COUNT(DISTINCT o.order_id) as total_orders,
                COUNT(DISTINCT o.customer_id) as unique_customers,
                COALESCE(SUM(o.total_amount), 0) as total_revenue,
                COALESCE(AVG(o.total_amount), 0) as avg_order_value,
                COUNT(DISTINCT CASE WHEN o.order_status = 'Delivered' THEN o.order_id END) as delivered_orders
            FROM regions r
            LEFT JOIN orders o ON r.region_id = o.region_id
            GROUP BY r.region_id, r.region_name;
CREATE INDEX idx_customers_region ON customers(region_id);
CREATE INDEX idx_employees_department ON employees(department_id);
CREATE INDEX idx_employees_manager ON employees(manager_id);
CREATE INDEX idx_products_category ON products(category_id);
CREATE INDEX idx_products_supplier ON products(supplier_id);
CREATE INDEX idx_orders_customer ON orders(customer_id);
CREATE INDEX idx_orders_employee ON orders(employee_id);
CREATE INDEX idx_orders_region ON orders(region_id);
CREATE INDEX idx_order_details_order ON order_details(order_id);
CREATE INDEX idx_order_details_product ON order_details(product_id);
CREATE INDEX idx_reviews_product ON reviews(product_id);
CREATE INDEX idx_reviews_customer ON reviews(customer_id);
CREATE INDEX idx_orders_date ON orders(order_date);
CREATE INDEX idx_customers_registration ON customers(registration_date);
CREATE INDEX idx_employees_hire_date ON employees(hire_date);
CREATE INDEX idx_customers_email ON customers(email);
CREATE INDEX idx_employees_email ON employees(email);
CREATE INDEX idx_products_name ON products(product_name);
CREATE INDEX idx_orders_status ON orders(order_status);
CREATE INDEX idx_orders_customer_date ON orders(customer_id, order_date);
CREATE INDEX idx_products_category_active ON products(category_id, is_active);
CREATE INDEX idx_customers_type_active ON customers(customer_type, is_active);
COMMIT;
